"use client";

import { createContext, type ReactNode, useContext, useMemo } from "react";

export interface SpringConfig {
  stiffness: number;
  damping: number;
}

export interface ChartConfigValue {
  /** Crosshair indicator, tooltip dot, date pill. */
  tooltipSpring: SpringConfig;
  /** Floating tooltip panel. */
  tooltipBoxSpring: SpringConfig;
  /** Line/area hover-highlight band (x + width). */
  highlightSpring: SpringConfig;
}

export const DEFAULT_CHART_CONFIG: ChartConfigValue = {
  tooltipSpring: { stiffness: 300, damping: 30 },
  tooltipBoxSpring: { stiffness: 100, damping: 20 },
  highlightSpring: { stiffness: 180, damping: 28 },
};

const ChartConfigContext = createContext<ChartConfigValue | null>(null);

export interface ChartConfigProviderProps {
  value?: Partial<ChartConfigValue>;
  children: ReactNode;
}

export function ChartConfigProvider({
  value,
  children,
}: ChartConfigProviderProps) {
  const merged = useMemo<ChartConfigValue>(
    () => ({
      ...DEFAULT_CHART_CONFIG,
      ...value,
    }),
    [value]
  );

  return (
    <ChartConfigContext.Provider value={merged}>
      {children}
    </ChartConfigContext.Provider>
  );
}

export function useChartConfig(): ChartConfigValue {
  return useContext(ChartConfigContext) ?? DEFAULT_CHART_CONFIG;
}

const DEFAULT_TOOLTIP_BOX_DAMPING =
  DEFAULT_CHART_CONFIG.tooltipBoxSpring.damping;

/** Maps a damping slider to the floating tooltip panel follow spring. `0` = instant. */
export function resolveTooltipBoxMotion(damping?: number): {
  animate: boolean;
  springConfig: SpringConfig;
} {
  if (damping === 0) {
    return {
      animate: false,
      springConfig: DEFAULT_CHART_CONFIG.tooltipBoxSpring,
    };
  }

  const effectiveDamping = damping ?? DEFAULT_TOOLTIP_BOX_DAMPING;
  let stiffness = DEFAULT_CHART_CONFIG.tooltipBoxSpring.stiffness;

  if (effectiveDamping < DEFAULT_TOOLTIP_BOX_DAMPING) {
    const t =
      (DEFAULT_TOOLTIP_BOX_DAMPING - effectiveDamping) /
      DEFAULT_TOOLTIP_BOX_DAMPING;
    stiffness += t * 400;
  } else if (effectiveDamping > DEFAULT_TOOLTIP_BOX_DAMPING) {
    const t =
      (effectiveDamping - DEFAULT_TOOLTIP_BOX_DAMPING) /
      (100 - DEFAULT_TOOLTIP_BOX_DAMPING);
    stiffness -= t * 85;
  }

  return {
    animate: true,
    springConfig: {
      stiffness: Math.max(12, Math.round(stiffness)),
      damping: effectiveDamping,
    },
  };
}

/** Vertical fade on the tooltip crosshair indicator. */
export type IndicatorFadeEdges = "both" | "none" | "top" | "bottom";

export interface VerticalFadeSides {
  top: boolean;
  bottom: boolean;
  any: boolean;
}

export function resolveVerticalFadeSides(
  fade: IndicatorFadeEdges | boolean
): VerticalFadeSides {
  if (fade === false || fade === "none") {
    return { top: false, bottom: false, any: false };
  }
  if (fade === true || fade === "both") {
    return { top: true, bottom: true, any: true };
  }
  if (fade === "top") {
    return { top: true, bottom: false, any: true };
  }
  return { top: false, bottom: true, any: true };
}

export interface IndicatorFadeGradientStop {
  offset: string;
  opacity: number;
}

/** Opacity stops for the crosshair vertical gradient. */
export function indicatorFadeGradientStops(
  sides: VerticalFadeSides,
  fadeLengthPercent = 10
): IndicatorFadeGradientStop[] {
  const fade = Math.min(40, Math.max(2, fadeLengthPercent));
  const innerEnd = 100 - fade;

  if (!sides.any) {
    return [{ offset: "0%", opacity: 1 }];
  }

  if (sides.top && sides.bottom) {
    return [
      { offset: "0%", opacity: 0 },
      { offset: `${fade}%`, opacity: 1 },
      { offset: "50%", opacity: 1 },
      { offset: `${innerEnd}%`, opacity: 1 },
      { offset: "100%", opacity: 0 },
    ];
  }

  if (sides.top) {
    return [
      { offset: "0%", opacity: 0 },
      { offset: `${fade}%`, opacity: 1 },
      { offset: "100%", opacity: 1 },
    ];
  }

  return [
    { offset: "0%", opacity: 1 },
    { offset: `${innerEnd}%`, opacity: 1 },
    { offset: "100%", opacity: 0 },
  ];
}

"use client";

import { motion, useSpring } from "motion/react";
import { memo, useEffect, useMemo } from "react";
import { createPortal } from "react-dom";
import {
  resolveTooltipBoxMotion,
  type SpringConfig,
  useChartConfig,
} from "../chart-config-context";
import {
  chartCssVars,
  type LineConfig,
  type Margin,
  type TooltipData,
  useChart,
  useChartPortalContainer,
  useChartStable,
} from "../chart-context";
import { formatBandRange, weekdayDateFmt } from "../chart-formatters";
import type { IndicatorFadeEdges } from "../indicator-fade";
import { DateTicker } from "./date-ticker";
import { TooltipBox, type TooltipBoxProps } from "./tooltip-box";
import { TooltipContent, type TooltipRow } from "./tooltip-content";
import { TooltipDot } from "./tooltip-dot";
import { TooltipIndicator } from "./tooltip-indicator";

export interface ChartTooltipProps {
  /** Whether to show the date pill at bottom. Default: true */
  showDatePill?: boolean;
  /**
   * Whether to show the crosshair indicator line. Default: `true` for
   * line / area / composed / scatter charts, `false` inside `BarChart`
   * (vertical and horizontal) and `ScatterChart` with `jitter` (hover snaps to
   * the nearest point, not a date) — pass `showCrosshair` to opt in.
   */
  showCrosshair?: boolean;
  /** Whether to show dots on the lines. Default: true */
  showDots?: boolean;
  /**
   * Dot style: filled circle with a soft same-color halo, or transparent ring.
   * Default: "dot"
   */
  dotVariant?: "dot" | "ring";
  /** Dot core / ring radius in pixels. Default: 5 */
  dotSize?: number;
  /**
   * `dot` variant: halo radius as a multiple of the core radius. `0` hides the halo.
   * Default: `2.6`
   */
  dotHaloScale?: number;
  /** `dot` variant: halo opacity (0–1). Default: `0.3` */
  dotHaloOpacity?: number;
  /** `dot` variant: blur (px) on the halo for a soft glow. `0` = crisp disc. Default: `0` */
  dotHaloBlur?: number;
  /** Ring corner radius as a fraction of side length (0 = square, 0.5 = circle). */
  dotRadiusFraction?: number;
  /** Multiplier applied to the computed dot / ring pixel radius. Default: 1 */
  dotScale?: number;
  /**
   * Ring stroke width in pixels (default `1.5`). For the `dot` variant, draws a
   * background-colored outline around the core (default `0`, none).
   */
  dotStrokeWidth?: number;
  /**
   * Color for the crosshair/indicator line. When a function, receives the hovered point
   * (e.g. for candlestick: match candle color from close vs open). Default: --chart-crosshair.
   */
  indicatorColor?: string | ((point: Record<string, unknown>) => string);
  /**
   * Bottom colour of a vertical crosshair ramp: the crosshair blends from
   * `indicatorColor` (top) to this colour (bottom). Composes with the fade.
   */
  indicatorEndColor?: string;
  /**
   * Where the crosshair ends: `"plot"` spans the full plot height, `"point"`
   * stops at the hovered point (the topmost dot). Default: `"plot"`.
   */
  indicatorEnd?: "plot" | "point";
  /** Custom content renderer for the tooltip box */
  content?: (props: {
    point: Record<string, unknown>;
    index: number;
  }) => React.ReactNode;
  /** Custom row renderer - return array of TooltipRow */
  rows?: (point: Record<string, unknown>) => TooltipRow[];
  /**
   * Override tooltip dot fill. When omitted and `rows` is set, dot colors match row colors.
   * When a function, receives the hovered point and line config.
   */
  dotColor?:
    | string
    | ((point: Record<string, unknown>, line: LineConfig) => string);
  /** Additional content to show below rows (e.g., markers) */
  children?: React.ReactNode;
  /** Custom class name */
  className?: string;
  /** Optional labels aligned with chart data for the x-axis ticker. */
  dateLabels?: string[];
  /** Per-chart override for the crosshair / dot / date-pill spring. */
  springConfig?: SpringConfig;
  /**
   * When `true`, the floating panel uses the crosshair spring and stays in sync.
   * Default `false` — panel follow uses `damping` (`20`).
   */
  matchCrosshair?: boolean;
  /**
   * Spring damping for the floating tooltip panel when `matchCrosshair` is `false`.
   * `0` disables spring motion (instant). Default: `20`.
   */
  damping?: number;
  /** SVG stroke dash pattern for the crosshair. Omit for solid. */
  indicatorDasharray?: string;
  /** Vertical crosshair fade: `both`, `top`, `bottom`, or `none` (solid). Default: `both`. */
  indicatorFadeEdges?: IndicatorFadeEdges;
  /** Crosshair fade zone size (% of height). Default: `10`. */
  indicatorFadeLength?: number;
  /** Per-chart override for the floating-panel spring. */
  boxSpringConfig?: SpringConfig;
  /** Inline styles for the tooltip panel (background, blur, etc.). */
  panelStyle?: React.CSSProperties;
  /**
   * Tooltip panel background color (CSS variable or color value).
   * Default: `var(--chart-tooltip-background)`.
   */
  backgroundColor?: string;
  /** Fade the panel out when hover ends. Default: true */
  exit?: boolean;
  /**
   * Extra gap (px) between the top of the plot and the panel when it is pinned
   * to the top (vertical charts without a single active point). Default: `0`.
   */
  topOffset?: number;
}

interface ChartTooltipInnerProps extends ChartTooltipProps {
  container: HTMLElement;
}

/**
 * Hovered point for nearest-point hover: `activeDataKey`'s point, else the
 * first series with a value in the row. Positions are plot-relative.
 */
function resolveActivePoint(
  tooltipData: TooltipData | null,
  lines: LineConfig[]
): { line: LineConfig; index: number; x: number; y: number } | null {
  if (!tooltipData) {
    return null;
  }
  const { activeDataKey, xPositions, yPositions } = tooltipData;
  const hasY = (line: LineConfig) => yPositions[line.dataKey] !== undefined;
  const line =
    lines.find((l) => l.dataKey === activeDataKey && hasY(l)) ??
    lines.find(hasY);
  const y = line ? yPositions[line.dataKey] : undefined;
  if (!line || y === undefined) {
    return null;
  }
  return {
    line,
    index: lines.indexOf(line),
    x: xPositions?.[line.dataKey] ?? tooltipData.x,
    y,
  };
}

/** Smallest (topmost) hovered y across series — `indicatorEnd="point"`. */
function resolveTopmostPointY(
  tooltipData: TooltipData | null,
  lines: LineConfig[]
): number | undefined {
  if (!tooltipData) {
    return undefined;
  }
  let topmost: number | undefined;
  for (const line of lines) {
    const y = tooltipData.yPositions[line.dataKey];
    if (y !== undefined && (topmost === undefined || y < topmost)) {
      topmost = y;
    }
  }
  return topmost;
}

/** TooltipBox position props for the hovered row / point. */
function resolveBoxPlacement({
  activePoint,
  tooltipData,
  lines,
  margin,
  isHorizontal,
  xWithMargin,
  topOffset,
}: {
  activePoint: ReturnType<typeof resolveActivePoint>;
  tooltipData: TooltipData | null;
  lines: LineConfig[];
  margin: Margin;
  isHorizontal: boolean;
  xWithMargin: number;
  topOffset: number;
}): Pick<TooltipBoxProps, "x" | "y" | "top" | "flipX" | "replayOnFlip"> {
  if (activePoint) {
    // Beside the hovered point, vertically centred + clamped. The side is
    // picked from the column so a column's points share it, and a flip springs
    // across rather than replaying the entrance.
    return {
      flipX: xWithMargin,
      replayOnFlip: false,
      x: activePoint.x + margin.left,
      y: activePoint.y + margin.top,
    };
  }
  if (isHorizontal) {
    // Horizontal charts: centre on the first line's y (middle of the bar).
    const firstLineDataKey = lines[0]?.dataKey;
    const firstLineY = firstLineDataKey
      ? (tooltipData?.yPositions[firstLineDataKey] ?? 0)
      : 0;
    return { x: xWithMargin, y: firstLineY + margin.top };
  }
  const top = margin.top + topOffset;
  return { top, x: xWithMargin, y: top };
}

const ChartTooltipInner = memo(function ChartTooltipInner({
  showDatePill = true,
  showCrosshair: showCrosshairProp,
  showDots = true,
  dotVariant = "dot",
  dotSize = 5,
  dotHaloScale,
  dotHaloOpacity,
  dotHaloBlur,
  dotRadiusFraction,
  dotScale = 1,
  dotStrokeWidth,
  indicatorColor: indicatorColorProp,
  indicatorEndColor,
  indicatorEnd = "plot",
  content,
  rows: rowsRenderer,
  dotColor: dotColorProp,
  children,
  className = "",
  container,
  springConfig,
  matchCrosshair = false,
  damping,
  indicatorDasharray,
  indicatorFadeEdges,
  indicatorFadeLength,
  boxSpringConfig,
  panelStyle,
  backgroundColor,
  dateLabels: dateLabelsProp,
  exit = true,
  topOffset = 0,
}: ChartTooltipInnerProps) {
  const {
    tooltipData,
    width,
    height,
    innerHeight,
    margin,
    columnWidth,
    lines,
    bands,
    xAccessor,
    dateLabels: contextDateLabels,
    containerRef,
    orientation,
    barXAccessor,
    bandWidth,
    squareSnap,
    nearestPointHover,
  } = useChart();
  const tooltipBands = useMemo(
    () => (bands ?? []).filter((band) => band.showInTooltip),
    [bands]
  );
  const { tooltipSpring } = useChartConfig();
  const dateLabels = dateLabelsProp ?? contextDateLabels;

  const isHorizontal = orientation === "horizontal";
  // Bar charts (any orientation) and nearest-point hover (jittered scatter)
  // hide the crosshair line by default.
  const showCrosshair =
    showCrosshairProp ?? !(barXAccessor || nearestPointHover);
  const discreteInteraction = dateLabels.length > 60;

  const resolvedDotSize = useMemo(() => {
    if (dotVariant !== "ring" || !bandWidth || lines.length === 0) {
      return dotSize * dotScale;
    }
    const seriesCount = lines.length;
    const gap = squareSnap?.groupGap ?? (seriesCount > 1 ? 4 : 0);
    const squareSize = (bandWidth - gap * (seriesCount - 1)) / seriesCount;
    return (squareSize / 2) * dotScale;
  }, [
    bandWidth,
    dotScale,
    dotSize,
    dotVariant,
    lines.length,
    squareSnap?.groupGap,
  ]);
  const boxMotion = useMemo(() => {
    if (boxSpringConfig) {
      return {
        animate: !discreteInteraction,
        springConfig: boxSpringConfig,
      };
    }
    if (matchCrosshair) {
      return {
        animate: !discreteInteraction,
        springConfig: springConfig ?? tooltipSpring,
      };
    }
    return resolveTooltipBoxMotion(damping);
  }, [
    boxSpringConfig,
    damping,
    discreteInteraction,
    matchCrosshair,
    springConfig,
    tooltipSpring,
  ]);

  const visible = tooltipData !== null;
  const x = tooltipData?.x ?? 0;
  const xWithMargin = x + margin.left;

  // Nearest-point hover (jittered scatter): the dot and panel follow the
  // hovered point, not the column / first series.
  const activePoint = nearestPointHover
    ? resolveActivePoint(tooltipData, lines)
    : null;
  const boxPlacement = resolveBoxPlacement({
    activePoint,
    tooltipData,
    lines,
    margin,
    isHorizontal,
    xWithMargin,
    topOffset,
  });

  const tooltipRows = useMemo(() => {
    if (!tooltipData) {
      return [];
    }

    if (rowsRenderer) {
      return rowsRenderer(tooltipData.point);
    }

    // Default: generate rows from registered lines, then `<Band>` ranges.
    // With nearest-point hover (jittered scatter) a row may hold only some
    // series — skip the rest.
    const rowLines = nearestPointHover
      ? lines.filter(
          (line) => typeof tooltipData.point[line.dataKey] === "number"
        )
      : lines;
    const rows: TooltipRow[] = rowLines.map((line) => ({
      color: line.stroke,
      label: line.dataKey,
      value: (tooltipData.point[line.dataKey] as number) ?? 0,
    }));
    for (const band of tooltipBands) {
      const value = formatBandRange(
        tooltipData.point,
        band.upperKey,
        band.lowerKey
      );
      if (value != null) {
        rows.push({ color: band.color, label: band.label, value });
      }
    }
    return rows;
  }, [tooltipData, lines, tooltipBands, rowsRenderer, nearestPointHover]);

  // One dot per band edge (deduped; edges shared with a `<Line>` use its dot).
  const bandDots = useMemo(() => {
    const lineKeys = new Set(lines.map((line) => line.dataKey));
    const seen = new Set<string>();
    const dots: { key: string; color: string }[] = [];
    for (const band of tooltipBands) {
      for (const key of [band.upperKey, band.lowerKey]) {
        if (lineKeys.has(key) || seen.has(key)) {
          continue;
        }
        seen.add(key);
        dots.push({ key, color: band.color });
      }
    }
    return dots;
  }, [lines, tooltipBands]);

  const resolveDotColor = useMemo(() => {
    return (line: LineConfig, index: number): string => {
      if (rowsRenderer && tooltipRows[index]?.color) {
        return tooltipRows[index].color;
      }
      if (dotColorProp != null) {
        if (typeof dotColorProp === "function" && tooltipData) {
          return dotColorProp(tooltipData.point, line);
        }
        if (typeof dotColorProp === "string") {
          return dotColorProp;
        }
      }
      return line.stroke;
    };
  }, [dotColorProp, rowsRenderer, tooltipData, tooltipRows]);

  // Resolve indicator color (static or from hovered point)
  const indicatorColor = useMemo(() => {
    if (indicatorColorProp == null) {
      return chartCssVars.crosshair;
    }
    if (typeof indicatorColorProp === "function") {
      return tooltipData
        ? indicatorColorProp(tooltipData.point)
        : chartCssVars.crosshair;
    }
    return indicatorColorProp;
  }, [indicatorColorProp, tooltipData]);

  const indicatorBottom =
    indicatorEnd === "point"
      ? resolveTopmostPointY(tooltipData, lines)
      : undefined;

  // Title from date or category
  const title = useMemo(() => {
    if (!tooltipData) {
      return undefined;
    }
    // For bar charts (horizontal or vertical), use the category name
    if (barXAccessor) {
      return barXAccessor(tooltipData.point);
    }
    // For line/area charts, use the date
    return weekdayDateFmt.format(xAccessor(tooltipData.point));
  }, [tooltipData, barXAccessor, xAccessor]);

  const tooltipContent = (
    <>
      {/* Crosshair indicator - rendered as SVG overlay */}
      {showCrosshair && (
        <svg
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 overflow-visible"
          height="100%"
          width="100%"
        >
          <g transform={`translate(${margin.left},${margin.top})`}>
            <TooltipIndicator
              animate={!discreteInteraction}
              bottom={indicatorBottom}
              colorEdge={indicatorColor}
              colorEnd={indicatorEndColor}
              colorMid={indicatorColor}
              columnWidth={columnWidth}
              fadeEdges={
                indicatorDasharray ? "none" : (indicatorFadeEdges ?? "both")
              }
              fadeLength={indicatorFadeLength}
              height={innerHeight}
              springConfig={springConfig}
              strokeDasharray={indicatorDasharray}
              visible={visible}
              width="line"
              x={x}
            />
          </g>
        </svg>
      )}

      {/* Dots on bars/lines - show for vertical charts only */}
      {showDots && visible && !isHorizontal && (
        <svg
          aria-hidden="true"
          className="pointer-events-none absolute inset-0 overflow-visible"
          height="100%"
          width="100%"
        >
          <g transform={`translate(${margin.left},${margin.top})`}>
            {nearestPointHover
              ? // One dot that springs between points (any series) instead of
                // one per series mounting / unmounting as rows change.
                activePoint && (
                  <TooltipDot
                    color={resolveDotColor(activePoint.line, activePoint.index)}
                    cornerRadiusFraction={
                      dotVariant === "ring" ? dotRadiusFraction : undefined
                    }
                    haloBlur={dotHaloBlur}
                    haloOpacity={dotHaloOpacity}
                    haloScale={dotHaloScale}
                    size={resolvedDotSize}
                    springConfig={springConfig}
                    strokeColor={chartCssVars.background}
                    strokeWidth={dotStrokeWidth}
                    variant={dotVariant}
                    visible={visible}
                    x={activePoint.x}
                    y={activePoint.y}
                  />
                )
              : lines.map((line, index) => (
                  <TooltipDot
                    color={resolveDotColor(line, index)}
                    cornerRadiusFraction={
                      dotVariant === "ring" ? dotRadiusFraction : undefined
                    }
                    haloBlur={dotHaloBlur}
                    haloOpacity={dotHaloOpacity}
                    haloScale={dotHaloScale}
                    key={line.dataKey}
                    size={resolvedDotSize}
                    springConfig={springConfig}
                    strokeColor={chartCssVars.background}
                    strokeWidth={dotStrokeWidth}
                    variant={dotVariant}
                    visible={visible}
                    x={tooltipData?.xPositions?.[line.dataKey] ?? x}
                    y={tooltipData?.yPositions[line.dataKey] ?? 0}
                  />
                ))}
            {bandDots.map((dot) => {
              const y = tooltipData?.yPositions[dot.key];
              if (y == null) {
                return null;
              }
              return (
                <TooltipDot
                  color={
                    typeof dotColorProp === "string" ? dotColorProp : dot.color
                  }
                  cornerRadiusFraction={
                    dotVariant === "ring" ? dotRadiusFraction : undefined
                  }
                  haloBlur={dotHaloBlur}
                  haloOpacity={dotHaloOpacity}
                  haloScale={dotHaloScale}
                  key={`band-${dot.key}`}
                  size={resolvedDotSize}
                  springConfig={springConfig}
                  strokeColor={chartCssVars.background}
                  strokeWidth={dotStrokeWidth}
                  variant={dotVariant}
                  visible={visible}
                  x={x}
                  y={y}
                />
              );
            })}
          </g>
        </svg>
      )}

      {/* Tooltip Box */}
      <TooltipBox
        animate={boxMotion.animate}
        backgroundColor={backgroundColor}
        className={className}
        containerHeight={height}
        containerRef={containerRef}
        containerWidth={width}
        exit={exit}
        panelStyle={panelStyle}
        springConfig={boxMotion.springConfig}
        {...boxPlacement}
        visible={visible}
      >
        {content && tooltipData
          ? content({
              point: tooltipData.point,
              index: tooltipData.index,
            })
          : !content && (
              <TooltipContent rows={tooltipRows} title={title}>
                {children}
              </TooltipContent>
            )}
      </TooltipBox>

      {/* Date/Category Ticker - only show for vertical charts */}
      <DatePillTracker
        currentIndex={tooltipData?.index ?? 0}
        discreteInteraction={discreteInteraction}
        enabled={showDatePill && !isHorizontal}
        labels={dateLabels}
        springConfig={springConfig}
        visible={visible}
        xWithMargin={xWithMargin}
      />
    </>
  );

  return createPortal(tooltipContent, container);
});

export function ChartTooltip(props: ChartTooltipProps) {
  const { containerRef } = useChartStable();

  const container = useChartPortalContainer(containerRef);
  if (!container) {
    return null;
  }

  return <ChartTooltipInner {...props} container={container} />;
}

ChartTooltip.displayName = "ChartTooltip";

interface DatePillTrackerProps {
  enabled: boolean;
  visible: boolean;
  labels: string[];
  currentIndex: number;
  xWithMargin: number;
  discreteInteraction: boolean;
  springConfig?: SpringConfig;
}

// Inner-only-on-visible so `useSpring` initializes at the real cursor x
// instead of `margin.left` on first hover.
function DatePillTracker(props: DatePillTrackerProps) {
  if (!(props.enabled && props.visible && props.labels.length > 0)) {
    return null;
  }
  return <DatePillTrackerInner {...props} />;
}

function DatePillTrackerInner({
  labels,
  currentIndex,
  xWithMargin,
  discreteInteraction,
  springConfig,
  visible,
}: DatePillTrackerProps) {
  const { tooltipSpring } = useChartConfig();
  const effectiveSpring = springConfig ?? tooltipSpring;
  const animatedX = useSpring(xWithMargin, effectiveSpring);

  if (!discreteInteraction) {
    animatedX.set(xWithMargin);
  }

  // biome-ignore lint/correctness/useExhaustiveDependencies: we need to jump the animatedX when the visible prop changes
  useEffect(() => {
    animatedX.set(xWithMargin);
  }, [animatedX, visible]);

  return (
    <motion.div
      className="pointer-events-none absolute z-50 w-max"
      style={{
        left: discreteInteraction ? xWithMargin : animatedX,
        transform: "translateX(-50%)",
        bottom: 4,
      }}
    >
      <DateTicker
        currentIndex={currentIndex}
        labels={labels}
        visible={visible}
      />
    </motion.div>
  );
}

export default ChartTooltip;

"use client";

import {
  AnimatePresence,
  type MotionValue,
  motion,
  useReducedMotion,
  useSpring,
} from "motion/react";
import type { RefObject } from "react";
import { useLayoutEffect, useRef, useState } from "react";
import { createPortal } from "react-dom";
import { cn } from "@/lib/utils";
import { type SpringConfig, useChartConfig } from "../chart-config-context";
import { chartCssVars, useChartPortalContainer } from "../chart-context";

export interface TooltipBoxProps {
  /** X position in pixels (relative to container) */
  x: number;
  /** Y position in pixels (relative to container) */
  y: number;
  /** Whether the tooltip is visible */
  visible: boolean;
  /** Container ref for portal rendering */
  containerRef: RefObject<HTMLDivElement | null>;
  /** Container width for flip detection */
  containerWidth: number;
  /** Container height for bounds clamping */
  containerHeight: number;
  /** Offset from the target position */
  offset?: number;
  /** Custom class name */
  className?: string;
  /** Tooltip content */
  children: React.ReactNode;
  /** Override left position (bypasses internal calculation) */
  left?: number | ReturnType<typeof useSpring>;
  /** Override top position (bypasses internal calculation) */
  top?: number | ReturnType<typeof useSpring>;
  /** Force flip direction (for custom positioning) */
  flipped?: boolean;
  /**
   * X (container px) that decides which side the panel opens on. Default: `x`.
   * Nearest-point hover passes the column x so every point in a column opens
   * on the same side (no flip — and entrance replay — between nearby points).
   */
  flipX?: number;
  /** Per-chart override; falls back to `ChartConfigProvider.tooltipBoxSpring`. */
  springConfig?: SpringConfig;
  /** Animate panel position with a spring. Default: true */
  animate?: boolean;
  /** Fade/scale the panel on show. Default: true */
  entrance?: boolean;
  /**
   * Fade the panel out when `visible` turns false (via `AnimatePresence`).
   * Requires `entrance`. Keep the box mounted and toggle `visible` (rather
   * than unmounting it) so the exit can play. Default: true
   */
  exit?: boolean;
  /**
   * Replay the panel entrance when it flips sides. `false` springs the panel
   * across instead (used by nearest-point hover, where neighbouring points
   * can sit on either side of the flip line). Default: true
   */
  replayOnFlip?: boolean;
  /** Inline styles for the inner tooltip panel. */
  panelStyle?: React.CSSProperties;
  /**
   * Tooltip panel background color (CSS variable or color value).
   * Default: `var(--chart-tooltip-background)`.
   */
  backgroundColor?: string;
}

/**
 * Popover-style panel: rounded, 1px border, soft layered shadow and a 1px
 * edge highlight (`before:`) — matches shadcn / coss popovers using only theme
 * tokens (`border`, `--radius`) and Tailwind utilities.
 */
export const TOOLTIP_PANEL_CLASS_NAME =
  "relative min-w-[160px] rounded-xl border not-dark:bg-clip-padding text-chart-tooltip-foreground shadow-lg/5 before:pointer-events-none before:absolute before:inset-0 before:rounded-[calc(var(--radius-xl)-1px)] before:shadow-[0_1px_rgb(0_0_0/0.04)] dark:before:shadow-[0_-1px_rgb(255_255_255/0.06)]";

/** Clips content to the panel's inner radius without clipping the edge highlight. */
export const TOOLTIP_PANEL_INNER_CLASS_NAME =
  "overflow-hidden rounded-[calc(var(--radius-xl)-1px)]";

/** Spring to `value`, or jump there (no animation) when `snap`. */
function moveTo(
  spring: MotionValue<number>,
  value: number,
  snap: boolean
): void {
  if (snap) {
    spring.jump(value);
  } else {
    spring.set(value);
  }
}

const DEFAULT_TOOLTIP_WIDTH = 180;
const DEFAULT_TOOLTIP_HEIGHT = 80;

/** Panel position beside the cursor: flips left near the right edge and is
 * clamped vertically inside the container. */
function resolveTooltipTarget({
  x,
  flipX = x,
  y,
  width,
  height,
  offset,
  containerWidth,
  containerHeight,
}: {
  x: number;
  flipX?: number;
  y: number;
  width: number;
  height: number;
  offset: number;
  containerWidth: number;
  containerHeight: number;
}) {
  const flipped = flipX + width + offset > containerWidth;
  return {
    flipped,
    left: flipped ? x - offset - width : x + offset,
    top: Math.max(
      offset,
      Math.min(y - height / 2, containerHeight - height - offset)
    ),
  };
}

// Inner-only-on-visible so `useSpring` initializes at the cursor's actual x/y
// instead of (0, 0) on first hover.
export function TooltipBox(props: TooltipBoxProps) {
  const container = useChartPortalContainer(props.containerRef);
  if (!container) {
    return null;
  }
  const inner = props.visible ? (
    <TooltipBoxInner {...props} container={container} key="tooltip-box" />
  ) : null;
  if (props.exit !== false && props.entrance !== false) {
    return <AnimatePresence>{inner}</AnimatePresence>;
  }
  return inner;
}

function TooltipBoxInner({
  x,
  y,
  containerWidth,
  containerHeight,
  offset = 16,
  className = "",
  children,
  left: leftOverride,
  top: topOverride,
  flipped: flippedOverride,
  flipX,
  springConfig,
  animate = true,
  entrance = true,
  exit: _exit,
  replayOnFlip = true,
  panelStyle,
  backgroundColor = chartCssVars.tooltipBackground,
  container,
}: Omit<TooltipBoxProps, "visible" | "containerRef"> & {
  container: HTMLElement;
}) {
  const { tooltipBoxSpring } = useChartConfig();
  // Reduced motion: position jumps instead of springing and the panel skips
  // its scale/slide; opacity fades are kept.
  const reducedMotion = useReducedMotion() === true;
  const effectiveSpring = springConfig ?? tooltipBoxSpring;

  const tooltipRef = useRef<HTMLDivElement>(null);
  // Last measured panel size — only read in the layout effect below.
  const tooltipWidthRef = useRef(DEFAULT_TOOLTIP_WIDTH);
  const tooltipHeightRef = useRef(DEFAULT_TOOLTIP_HEIGHT);
  const [staticPosition, setStaticPosition] = useState({ left: x, top: y });
  // First measured position jumps (no spring from the estimated size).
  const hasPositionedRef = useRef(false);

  // Flip side + replay key for the panel entrance. Seeded from the default
  // size (the inner box mounts fresh on every show); refined from the measured
  // width in the layout effect, which only re-renders when the side changes.
  const [flip, setFlip] = useState(() => ({
    flipped: (flipX ?? x) + DEFAULT_TOOLTIP_WIDTH + offset > containerWidth,
    key: 0,
  }));
  const shouldFlipX = flip.flipped;

  const [initialTarget] = useState(() =>
    resolveTooltipTarget({
      x,
      flipX,
      y,
      width: DEFAULT_TOOLTIP_WIDTH,
      height: DEFAULT_TOOLTIP_HEIGHT,
      offset,
      containerWidth,
      containerHeight,
    })
  );
  const animatedLeft = useSpring(initialTarget.left, effectiveSpring);
  const animatedTop = useSpring(initialTarget.top, effectiveSpring);

  useLayoutEffect(() => {
    if (!tooltipRef.current) {
      return;
    }
    const el = tooltipRef.current;
    const w = el.offsetWidth;
    const h = el.offsetHeight;
    if (w > 0) {
      tooltipWidthRef.current = w;
    }
    if (h > 0) {
      tooltipHeightRef.current = h;
    }
    const target = resolveTooltipTarget({
      x,
      flipX,
      y,
      width: tooltipWidthRef.current,
      height: tooltipHeightRef.current,
      offset,
      containerWidth,
      containerHeight,
    });
    setFlip((prev) =>
      prev.flipped === target.flipped
        ? prev
        : { flipped: target.flipped, key: prev.key + 1 }
    );
    const tx = target.left;
    const ty = target.top;
    if (!animate) {
      setStaticPosition({ left: tx, top: ty });
      return;
    }
    const snap = reducedMotion || !hasPositionedRef.current;
    hasPositionedRef.current = true;
    if (leftOverride === undefined) {
      moveTo(animatedLeft, tx, snap);
    }
    if (topOverride === undefined) {
      moveTo(animatedTop, ty, snap);
    }
  }, [
    x,
    flipX,
    y,
    containerWidth,
    containerHeight,
    offset,
    leftOverride,
    topOverride,
    animate,
    animatedLeft,
    animatedTop,
    reducedMotion,
  ]);

  const flipKey = replayOnFlip ? flip.key : 0;

  const finalLeft = animate
    ? (leftOverride ?? animatedLeft)
    : staticPosition.left;
  const finalTop = animate ? (topOverride ?? animatedTop) : staticPosition.top;
  const isFlipped = flippedOverride ?? shouldFlipX;
  const transformOrigin = isFlipped ? "right top" : "left top";

  const panelClassName = cn(
    TOOLTIP_PANEL_CLASS_NAME,
    panelStyle?.backgroundColor === undefined &&
      backgroundColor === chartCssVars.tooltipBackground &&
      "bg-chart-tooltip-background",
    panelStyle?.backdropFilter === undefined && "backdrop-blur-md"
  );
  const panelStyleResolved = {
    transformOrigin,
    ...(panelStyle?.backgroundColor === undefined && {
      backgroundColor,
    }),
    ...panelStyle,
  };

  if (!entrance) {
    return createPortal(
      <div
        className={cn("pointer-events-none absolute z-50", className)}
        ref={tooltipRef}
        style={{ left: staticPosition.left, top: staticPosition.top }}
      >
        <div className={panelClassName} style={panelStyleResolved}>
          <div className={TOOLTIP_PANEL_INNER_CLASS_NAME}>{children}</div>
        </div>
      </div>,
      container
    );
  }

  return createPortal(
    <motion.div
      animate={{ opacity: 1 }}
      className={cn("pointer-events-none absolute z-50", className)}
      exit={{ opacity: 0 }}
      initial={{ opacity: 0 }}
      ref={tooltipRef}
      style={{ left: finalLeft, top: finalTop }}
      transition={{ duration: 0.1 }}
    >
      <motion.div
        animate={{ scale: 1, opacity: 1, x: 0 }}
        className={panelClassName}
        initial={
          reducedMotion
            ? { opacity: 0 }
            : { scale: 0.85, opacity: 0, x: isFlipped ? 20 : -20 }
        }
        key={flipKey}
        style={panelStyleResolved}
        transition={{ type: "spring", stiffness: 300, damping: 25 }}
      >
        <div className={TOOLTIP_PANEL_INNER_CLASS_NAME}>{children}</div>
      </motion.div>
    </motion.div>,
    container
  );
}

