"use client";

import { motion, useSpring } from "motion/react";
import { useEffect, useId } from "react";
import { type SpringConfig, useChartConfig } from "../chart-config-context";
import { chartCssVars } from "../chart-context";
import {
  type IndicatorFadeEdges,
  indicatorFadeGradientStops,
  resolveVerticalFadeSides,
} from "../indicator-fade";

export type IndicatorWidth =
  | number // Pixel width
  | "line" // 1px line (default)
  | "thin" // 2px
  | "medium" // 4px
  | "thick"; // 8px

export interface TooltipIndicatorProps {
  /** X position in pixels (center of the indicator) */
  x: number;
  /** Height of the indicator */
  height: number;
  /** Whether the indicator is visible */
  visible: boolean;
  /**
   * Width of the indicator - number (pixels) or preset.
   * Ignored if `span` is provided.
   */
  width?: IndicatorWidth;
  /**
   * Number of columns/days to span, with current point centered.
   * Requires `columnWidth` to be set.
   */
  span?: number;
  /** Width of a single column/day in pixels. Required when using `span`. */
  columnWidth?: number;
  /** Primary color at edges (10% and 90%) */
  colorEdge?: string;
  /** Secondary color at center (50%) */
  colorMid?: string;
  /**
   * Bottom colour for a vertical colour ramp: the indicator blends from
   * `colorMid` (top) to `colorEnd` (bottom). Composes with `fadeEdges`.
   */
  colorEnd?: string;
  /**
   * Y (px) where the indicator ends, e.g. the hovered point. Springs with the
   * indicator. Default: `height` (full plot).
   */
  bottom?: number;
  /** Vertical fade: both ends, top, bottom, or none (solid). */
  fadeEdges?: IndicatorFadeEdges | boolean;
  /** Fade zone size as a percentage of indicator height. Default: 10 */
  fadeLength?: number;
  /** Animate position with a spring. Default: true */
  animate?: boolean;
  /** Unique ID for the gradient. Default: generated per instance. */
  gradientId?: string;
  /** Per-chart override; falls back to `ChartConfigProvider.tooltipSpring`. */
  springConfig?: SpringConfig;
  /** SVG stroke dash pattern. When set, renders a dashed stroke instead of a solid fill. */
  strokeDasharray?: string;
}

function resolveWidth(width: IndicatorWidth): number {
  if (typeof width === "number") {
    return width;
  }
  switch (width) {
    case "line":
      return 1;
    case "thin":
      return 2;
    case "medium":
      return 4;
    case "thick":
      return 8;
    default:
      return 1;
  }
}

/** Colour at a gradient `offset` ("40%") on a top → bottom ramp. */
function verticalRampColor(top: string, end: string, offset: string): string {
  const percent = Number.parseFloat(offset);
  if (percent <= 0) {
    return top;
  }
  if (percent >= 100) {
    return end;
  }
  return `color-mix(in srgb, ${end} ${percent}%, ${top})`;
}

// Inner-only-on-visible so `useSpring` initializes at the real cursor x
// instead of 0 on first hover.
export function TooltipIndicator(props: TooltipIndicatorProps) {
  if (!props.visible) {
    return null;
  }
  return <TooltipIndicatorInner {...props} />;
}

function TooltipIndicatorInner({
  x,
  visible,
  height,
  width = "line",
  span,
  columnWidth,
  colorEdge = chartCssVars.crosshair,
  colorMid = chartCssVars.crosshair,
  colorEnd,
  bottom,
  fadeEdges = "both",
  fadeLength = 10,
  animate = true,
  gradientId: gradientIdProp,
  springConfig,
  strokeDasharray,
}: TooltipIndicatorProps) {
  // Per-instance id: a shared id makes every chart on the page resolve
  // `url(#…)` to the first chart's gradient (and its colours).
  const generatedId = useId();
  const gradientId =
    gradientIdProp ?? `tooltip-indicator-gradient-${generatedId}`;
  const { tooltipSpring } = useChartConfig();
  const effectiveSpring = springConfig ?? tooltipSpring;

  const pixelWidth =
    span !== undefined && columnWidth !== undefined
      ? span * columnWidth
      : resolveWidth(width);

  const rectX = x - pixelWidth / 2;
  const lineX = x;
  const endY = Math.max(0, Math.min(height, bottom ?? height));
  const animatedX = useSpring(rectX, effectiveSpring);
  const animatedLineX = useSpring(lineX, effectiveSpring);
  const animatedEndY = useSpring(endY, effectiveSpring);

  if (animate) {
    animatedX.set(rectX);
    animatedLineX.set(lineX);
    animatedEndY.set(endY);
  }

  // biome-ignore lint/correctness/useExhaustiveDependencies: we need to jump the animatedX when the visible prop changes
  useEffect(() => {
    animatedX.set(rectX);
    animatedLineX.set(lineX);
    animatedEndY.set(endY);
  }, [animatedLineX, animatedX, animatedEndY, endY, lineX, rectX, visible]);

  const indicatorFill = colorMid || colorEdge;
  const fadeSides = resolveVerticalFadeSides(fadeEdges);
  const dashed = Boolean(strokeDasharray);

  if (dashed) {
    const strokeWidth = Math.max(1, pixelWidth);
    return animate ? (
      <motion.line
        stroke={indicatorFill}
        strokeDasharray={strokeDasharray}
        strokeWidth={strokeWidth}
        x1={animatedLineX}
        x2={animatedLineX}
        y1={0}
        y2={animatedEndY}
      />
    ) : (
      <line
        stroke={indicatorFill}
        strokeDasharray={strokeDasharray}
        strokeWidth={strokeWidth}
        x1={lineX}
        x2={lineX}
        y1={0}
        y2={endY}
      />
    );
  }

  if (!(fadeSides.any || colorEnd)) {
    return animate ? (
      <motion.rect
        fill={indicatorFill}
        height={animatedEndY}
        width={pixelWidth}
        x={animatedX}
        y={0}
      />
    ) : (
      <rect
        fill={indicatorFill}
        height={endY}
        width={pixelWidth}
        x={rectX}
        y={0}
      />
    );
  }

  const fadeStops = indicatorFadeGradientStops(fadeSides, fadeLength);
  if (colorEnd && fadeStops.length === 1) {
    fadeStops.push({ offset: "100%", opacity: 1 });
  }

  return (
    <g>
      <defs>
        <linearGradient id={gradientId} x1="0%" x2="0%" y1="0%" y2="100%">
          {fadeStops.map((stop) => (
            <stop
              key={stop.offset}
              offset={stop.offset}
              style={{
                stopColor: colorEnd
                  ? verticalRampColor(indicatorFill, colorEnd, stop.offset)
                  : indicatorFill,
                stopOpacity: stop.opacity,
              }}
            />
          ))}
        </linearGradient>
      </defs>
      {animate ? (
        <motion.rect
          fill={`url(#${gradientId})`}
          height={animatedEndY}
          width={pixelWidth}
          x={animatedX}
          y={0}
        />
      ) : (
        <rect
          fill={`url(#${gradientId})`}
          height={endY}
          width={pixelWidth}
          x={rectX}
          y={0}
        />
      )}
    </g>
  );
}

TooltipIndicator.displayName = "TooltipIndicator";

export default TooltipIndicator;

"use client";

import { useEffect, useState } from "react";

/**
 * Default grace period (ms) before a tooltip hides after hover ends. Bridges
 * gaps between adjacent targets (heatmap cells, choropleth features) so the
 * panel springs to the next target instead of fading out and back in.
 */
export const TOOLTIP_HIDE_DELAY_MS = 120;

/**
 * Delays showing (`showDelay`) and hiding (`hideDelay`) hover tooltip data.
 * Once visible, changes to another target apply immediately.
 *
 * Immediate updates are applied during render ("adjust state when props
 * change") and delayed ones from timers, so no state is set synchronously in
 * an effect (React Compiler `react-hooks/set-state-in-effect`).
 */
export function useDelayedTooltipData<T>(
  tooltipData: T | null,
  showDelay = 0,
  hideDelay = TOOLTIP_HIDE_DELAY_MS
): T | null {
  const [displayData, setDisplayData] = useState<T | null>(null);
  const [prevTooltipData, setPrevTooltipData] = useState<T | null>(null);

  // The tooltip counts as showing while it has data on screen (including
  // while a hide is pending).
  const isShowing = displayData !== null;

  if (prevTooltipData !== tooltipData) {
    setPrevTooltipData(tooltipData);
    if (tooltipData) {
      if (isShowing || showDelay === 0) {
        setDisplayData(tooltipData);
      }
    } else if (hideDelay === 0) {
      setDisplayData(null);
    }
  }

  useEffect(() => {
    if (tooltipData) {
      if (displayData === tooltipData) {
        return;
      }
      const showTimer = setTimeout(() => {
        setDisplayData(tooltipData);
      }, showDelay);
      return () => clearTimeout(showTimer);
    }

    if (displayData === null) {
      return;
    }
    const hideTimer = setTimeout(() => {
      setDisplayData(null);
    }, hideDelay);
    return () => clearTimeout(hideTimer);
  }, [tooltipData, displayData, showDelay, hideDelay]);

  return displayData;
}

"use client";

import {
  type MotionValue,
  motion,
  useReducedMotion,
  useSpring,
} from "motion/react";
import { memo, type RefObject, useLayoutEffect, useMemo, useRef } from "react";

const TICKER_ITEM_HEIGHT = 24;
const TICKER_SPRING = { stiffness: 400, damping: 35 };
/** Full scroll stacks are skipped above this count — single label + instant updates. */
const COMPACT_TICKER_THRESHOLD = 60;

/** Retarget a spring, or snap it when motion should be instant. */
function driveSpring(
  value: MotionValue<number>,
  target: number,
  instant: boolean
) {
  if (instant) {
    value.jump(target);
  } else {
    value.set(target);
  }
}

interface TickerSegment {
  value: string;
  key: string;
  startIndex: number;
}

/** One entry per consecutive run of equal values, keyed by its start index. */
function toSegments(values: readonly string[]): TickerSegment[] {
  const segments: TickerSegment[] = [];
  values.forEach((value, index) => {
    if (segments.at(-1)?.value !== value) {
      segments.push({ value, key: `${value}-${index}`, startIndex: index });
    }
  });
  return segments;
}

/** Index of the segment containing label `index` (0 when out of range). */
function segmentIndexAt(
  segments: readonly TickerSegment[],
  index: number,
  total: number
) {
  if (index < 0 || index >= total) {
    return 0;
  }
  for (let i = segments.length - 1; i >= 0; i--) {
    const segment = segments[i];
    if (segment && segment.startIndex <= index) {
      return i;
    }
  }
  return 0;
}

/**
 * Widths of a stack's `[data-ticker-item]` children, re-measured when the
 * items or loaded fonts change. Drives `width` toward the active item so the
 * pill hugs the current label instead of the longest one (e.g. when switching
 * between Persian and Latin labels).
 */
function useActiveItemWidth(
  stackRef: RefObject<HTMLElement | null>,
  items: readonly unknown[],
  activeIndex: number,
  width: MotionValue<number>,
  reduceMotion: boolean
) {
  const widthsRef = useRef<number[]>([]);
  const activeIndexRef = useRef(activeIndex);
  // Synced before the measure effect below (layout effects run in order).
  useLayoutEffect(() => {
    activeIndexRef.current = activeIndex;
  });

  // biome-ignore lint/correctness/useExhaustiveDependencies: items change the rendered stack, so re-measure
  useLayoutEffect(() => {
    let cancelled = false;
    const measure = (snap: boolean) => {
      const stack = stackRef.current;
      if (cancelled || !stack) {
        return;
      }
      widthsRef.current = Array.from(
        stack.querySelectorAll<HTMLElement>("[data-ticker-item]"),
        (node) => node.getBoundingClientRect().width
      );
      const next = widthsRef.current[activeIndexRef.current];
      if (next === undefined) {
        return;
      }
      // First measure snaps so the pill never grows in from zero.
      driveSpring(width, next, snap || reduceMotion);
    };
    measure(widthsRef.current.length === 0);
    document.fonts?.ready.then(() => measure(false));
    return () => {
      cancelled = true;
    };
  }, [stackRef, items, width, reduceMotion]);

  // Follow the active item. A layout effect (not render) so the spring
  // retargets before paint without reading refs / mutating during render.
  useLayoutEffect(() => {
    const target = widthsRef.current[activeIndex];
    if (target !== undefined) {
      driveSpring(width, target, reduceMotion);
    }
  }, [activeIndex, width, reduceMotion]);
}

export interface DateTickerProps {
  currentIndex: number;
  labels: string[];
  visible: boolean;
}

const DateTickerCompact = memo(function DateTickerCompact({
  currentIndex,
  labels,
}: Omit<DateTickerProps, "visible">) {
  const reduceMotion = useReducedMotion() === true;
  const label = labels[currentIndex] ?? labels[0] ?? "";
  const labelItems = useMemo(() => [label], [label]);
  const stackRef = useRef<HTMLDivElement>(null);
  const width = useSpring(0, TICKER_SPRING);
  useActiveItemWidth(stackRef, labelItems, 0, width, reduceMotion);

  return (
    <div className="overflow-hidden rounded-full bg-zinc-900 px-4 py-1 text-white shadow-lg dark:bg-zinc-100 dark:text-zinc-900">
      <motion.div className="relative h-6" style={{ width }}>
        <motion.div
          className="absolute top-0 left-1/2 flex h-6 items-center"
          ref={stackRef}
          style={{ x: "-50%" }}
        >
          <span
            className="whitespace-nowrap font-medium text-sm"
            data-ticker-item
          >
            {label}
          </span>
        </motion.div>
      </motion.div>
    </div>
  );
});

const DateTickerInner = memo(function DateTickerInner({
  currentIndex,
  labels,
}: Omit<DateTickerProps, "visible">) {
  const reduceMotion = useReducedMotion() === true;

  // Parse labels into month and second-part (day or year) values
  const parsedLabels = useMemo(() => {
    return labels.map((label) => {
      const parts = label.split(" ");
      return { month: parts[0] || "", day: parts[1] || "" };
    });
  }, [labels]);

  // One segment per consecutive run (Jan → Feb → …). The second part (day for
  // daily data, year for monthly data) is segmented the same way, so it stays
  // still until it actually changes instead of scrolling through repeats.
  const monthSegments = useMemo(
    () => toSegments(parsedLabels.map((label) => label.month)),
    [parsedLabels]
  );
  const daySegments = useMemo(
    () => toSegments(parsedLabels.map((label) => label.day)),
    [parsedLabels]
  );

  const currentMonthIndex = segmentIndexAt(
    monthSegments,
    currentIndex,
    parsedLabels.length
  );
  const currentDayIndex = segmentIndexAt(
    daySegments,
    currentIndex,
    parsedLabels.length
  );

  // Animated Y offsets
  const dayY = useSpring(0, TICKER_SPRING);
  const monthY = useSpring(0, TICKER_SPRING);

  // Each stack's width follows its active item, so the pill resizes per label.
  const monthStackRef = useRef<HTMLDivElement>(null);
  const dayStackRef = useRef<HTMLDivElement>(null);
  const monthWidth = useSpring(0, TICKER_SPRING);
  const dayWidth = useSpring(0, TICKER_SPRING);
  useActiveItemWidth(
    monthStackRef,
    monthSegments,
    currentMonthIndex,
    monthWidth,
    reduceMotion
  );
  useActiveItemWidth(
    dayStackRef,
    daySegments,
    currentDayIndex,
    dayWidth,
    reduceMotion
  );

  // Scroll the stacks to the active day / month before paint.
  useLayoutEffect(() => {
    driveSpring(dayY, -currentDayIndex * TICKER_ITEM_HEIGHT, reduceMotion);
  }, [currentDayIndex, dayY, reduceMotion]);

  useLayoutEffect(() => {
    driveSpring(monthY, -currentMonthIndex * TICKER_ITEM_HEIGHT, reduceMotion);
  }, [currentMonthIndex, monthY, reduceMotion]);

  return (
    <div className="overflow-hidden rounded-full bg-zinc-900 px-4 py-1 text-white shadow-lg dark:bg-zinc-100 dark:text-zinc-900">
      <div className="relative h-6 overflow-hidden">
        <div className="flex items-center justify-center gap-1">
          {/* Month stack */}
          <motion.div
            className="relative h-6 overflow-hidden"
            style={{ width: monthWidth }}
          >
            <motion.div
              className="absolute top-0 left-1/2 flex flex-col items-center"
              ref={monthStackRef}
              style={{ x: "-50%", y: monthY }}
            >
              {monthSegments.map((segment) => (
                <div
                  className="flex h-6 shrink-0 items-center justify-center"
                  data-ticker-item
                  key={segment.key}
                >
                  <span className="whitespace-nowrap font-medium text-sm">
                    {segment.value}
                  </span>
                </div>
              ))}
            </motion.div>
          </motion.div>

          {/* Second-part stack (day or year) */}
          <motion.div
            className="relative h-6 overflow-hidden"
            style={{ width: dayWidth }}
          >
            <motion.div
              className="absolute top-0 left-1/2 flex flex-col items-center"
              ref={dayStackRef}
              style={{ x: "-50%", y: dayY }}
            >
              {daySegments.map((segment) => (
                <div
                  className="flex h-6 shrink-0 items-center justify-center"
                  data-ticker-item
                  key={segment.key}
                >
                  <span className="whitespace-nowrap font-medium text-sm">
                    {segment.value}
                  </span>
                </div>
              ))}
            </motion.div>
          </motion.div>
        </div>
      </div>
    </div>
  );
});

export function DateTicker({ currentIndex, labels, visible }: DateTickerProps) {
  if (!visible || labels.length === 0) {
    return null;
  }

  if (labels.length > COMPACT_TICKER_THRESHOLD) {
    return <DateTickerCompact currentIndex={currentIndex} labels={labels} />;
  }

  return <DateTickerInner currentIndex={currentIndex} labels={labels} />;
}

